package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaLock sync.RWMutex
	meta     = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata sets the application metadata.
// This should be called before creating windows, typically at the start of the application.
//
// Since: 2.2
func SetMetadata(m fyne.AppMetadata) {
	metaLock.Lock()
	defer metaLock.Unlock()

	meta = m
}

func getMetadata() fyne.AppMetadata {
	metaLock.RLock()
	defer metaLock.RUnlock()

	return meta
}

