package binding

import (
	"fmt"
	"sync"
)

// StringFormat is a binding that formats values from other bindings using sprintf.
//
// Since: 2.2
type StringFormat interface {
	String
	// AddListener attaches a new change listener to this binding.
	// Changing any of the source bindings will trigger the listener.
	AddListener(DataListener)
	// RemoveListener detaches a change listener from this binding.
	RemoveListener(DataListener)
	// Reload forces the formatted string to be recalculated from the current source values.
	Reload() error
}

type stringFormat struct {
	base
	format  string
	sources []DataItem
	lock    sync.RWMutex
	val     string
}

// NewSprintf returns a new StringFormat binding that will format values from the specified source bindings.
// The format string follows the same rules as fmt.Sprintf.
// Any changes to source bindings will automatically update the formatted result.
//
// Since: 2.2
func NewSprintf(format string, sources ...DataItem) StringFormat {
	if len(sources) == 0 {
		return &stringFormat{format: format, val: format}
	}

	sf := &stringFormat{
		format:  format,
		sources: sources,
	}

	// Attach listeners to all source bindings
	for _, src := range sources {
		src.AddListener(NewDataListener(func() {
			sf.Reload()
		}))
	}

	// Initial formatting
	sf.Reload()

	return sf
}

func (sf *stringFormat) AddListener(listener DataListener) {
	sf.lock.Lock()
	defer sf.lock.Unlock()
	sf.base.AddListener(listener)
}

func (sf *stringFormat) RemoveListener(listener DataListener) {
	sf.lock.Lock()
	defer sf.lock.Unlock()
	sf.base.RemoveListener(listener)
}

func (sf *stringFormat) Get() (string, error) {
	sf.lock.RLock()
	defer sf.lock.RUnlock()
	return sf.val, nil
}

func (sf *stringFormat) Set(string) error {
	// StringFormat is read-only
	return nil
}

func (sf *stringFormat) Reload() error {
	values := make([]interface{}, len(sf.sources))

	for i, src := range sf.sources {
		switch s := src.(type) {
		case String:
			if v, err := s.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = ""
			}
		case Bool:
			if v, err := s.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = false
			}
		case Float:
			if v, err := s.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = 0.0
			}
		case Int:
			if v, err := s.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = 0
			}
		case Untyped:
			if v, err := s.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = nil
			}
		default:
			values[i] = nil
		}
	}

	sf.lock.Lock()
	sf.val = fmt.Sprintf(sf.format, values...)
	sf.lock.Unlock()

	sf.trigger()
	return nil
}

