package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a validator that checks if all provided validators return nil.
// The returned validator will return nil only if all validators pass, otherwise returns
// the first error encountered.
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err != nil {
				return err
			}
		}
		return nil
	}
}

// NewAnyString creates a validator that checks if any of the provided validators return nil.
// The returned validator will return nil if at least one validator passes, otherwise returns
// an error indicating all validators failed.
//
// Since: 2.2
func NewAnyString(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		if len(validators) == 0 {
			return nil
		}

		for _, validator := range validators {
			if validator == nil {
				continue
			}
			if err := validator(text); err == nil {
				return nil
			}
		}
		return errors.New("no validator passed")
	}
}

